def _split_line(system: str, line: str) -> list[str]:
    if system == "A":
        return split_record(line)
    return line.split(",")


def _parse_date(system: str, raw: str) -> date:
    if system == "C":
        return datetime.strptime(raw.strip(), "%d/%m/%Y").date()
    return date.fromisoformat(raw.strip())


